em.qty * item.sell_price)"></td><td class="px-5 py-4"><button type="button" @click="removeItem(index)" class="rounded-lg px-2 py-1 text-rose-500 hover:bg-rose-50">×</button></td></tr></template></tbody><tfoot class="border-t border-slate-100 bg-slate-50"><tr><td colspan="3" class="px-5 py-4 text-right font-bold">Total</td><td class="px-5 py-4 text-right text-lg font-extrabold text-teal-700" x-text="format(total())"></td><td></td></tr></tfoot></table></div></div>
