    @push('scripts')<script>function saleForm(){return {items:[{key:Date.now(),product_id:'',search:'',qty:1,sell_price:0,stock:0,options:[]}],paid:0,addItem(){this.items.push({key:Date.now()+Math.random(),product_id:'',search:'',qty:1,sell_price:0,stock:0,options:[]})},removeItem(index){if(this.items.length>1)this.items.splice(index,1)},selectProduct(item,product){item.product_id=product.id;item.search=product.name+' ('+product.code+')';item.sell_price=product.sell_price;item.stock=product.stock;item.qty=Math.min(item.qty,product.stock||1);item.options=[]},async searchProducts(item){if(item.search.length<2){item.options=[];return}const response=await fetch('{{ route('sales.autocomplete') }}?q='+encodeURIComponent(item.search));item.options=await response.json()},total(){return this.items.reduce((sum,item)=>sum+(Number(item.qty)||0)*(Number(item.sell_price)||0),0)},format(value){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0)}}}</script>@endpush
